import{_ as a,c as s,o as i,ae as t}from"./chunks/framework.DEXG3EuZ.js";const k=JSON.parse('{"title":"AI Chat と Streaming","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/ai-chat.md","filePath":"ja/guide/ai-chat.md","lastUpdated":1792605191000}'),o={name:"ja/guide/ai-chat.md"};function d(c,e,n,r,p,h){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="ai-chat-と-streaming" tabindex="-1">AI Chat と Streaming <a class="header-anchor" href="#ai-chat-と-streaming" aria-label="Permalink to &quot;AI Chat と Streaming&quot;">​</a></h1><p>フロントエンドは Provider 非依存の <code>ChatProvider</code> と <code>AsyncIterable&lt;ChatChunk&gt;</code> を使います。<code>FetchStreamChatProvider</code> が <code>POST /api/ai/chat</code> を呼び、<code>parseSseStream</code> が <code>start / delta / usage / done / error</code> を解析します。</p><p><code>useStreamingChat</code> は Message、Streaming、Abort、Retry、Regenerate を管理します。Stop は <code>AbortController.abort()</code> を即時実行します。</p><p>Markdown は Raw HTML を無効にし、DOMPurify で再度 Sanitization します。AI HTML を信頼して <code>v-html</code> に直接渡してはいけません。大きい Syntax Highlighter は必要な Route で Dynamic Import します。</p><p>FastAPI は Gin JWT を検証し、Redis でユーザー単位に制限します。Provider Key は Backend だけに保存します。</p><h2 id="言語別の開始用プロンプト" tabindex="-1">言語別の開始用プロンプト <a class="header-anchor" href="#言語別の開始用プロンプト" aria-label="Permalink to &quot;言語別の開始用プロンプト&quot;">​</a></h2><p>チャットの空状態は JSON の <code>GET /api/ai/suggestions</code> を使います。言語別にキャッシュし、鮮度を五分間に設定して自動再試行を無効にしています。読み込み中、空の結果、通信失敗時には翻訳済みのローカル提案を使います。選択後は既存の送信・停止処理に進み、SSE 契約や会話の保存処理は変更しません。</p><p>クライアントは <code>zh-*</code> を <code>zh-CN</code>、<code>ja-*</code> を <code>ja-JP</code>、その他を <code>en-US</code> に変換します。FastAPI が受け付けるのはこの三つの値のみです。省略時は <code>en-US</code>、未対応の値は HTTP 422 です。言語は <code>locale</code> クエリで指定し、<code>Accept-Language</code> だけには依存しません。</p><p>単体アプリでは <code>VITE_AI_API_BASE_URL</code>（既定 <code>/api/ai</code>）で提案を取得し、開発プロキシを <code>VITE_AI_API_TARGET</code> で指定します。通常の業務通信は Gin に送ります。JSON は <code>src/api/modules/ai.ts</code>、ストリーミングはプロバイダーと composable が担当します。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { getChatSuggestions } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@/api/modules/ai&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> prompts</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getChatSuggestions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(locale, signal, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/api/ai&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="ストリームの終了と後処理" tabindex="-1">ストリームの終了と後処理 <a class="header-anchor" href="#ストリームの終了と後処理" aria-label="Permalink to &quot;ストリームの終了と後処理&quot;">​</a></h2><p>パーサーは旧 Mock の <code>start.conversationId</code> / <code>done</code> と FastAPI の <code>start.id</code> / <code>finish</code> の両方を受け取り、内部の <code>ChatChunk</code> に変換します。UTF-8 の文字や CRLF 区切りが通信チャンクをまたいでも処理できます。終了イベントで読み取りを終え、途中終了や解析失敗時には reader をキャンセルしてロックを解放します。HTTP エラーではサーバーの <code>message</code> と Request ID を保持します。</p><p>停止やクリアでは送信中の状態をすぐに解除し、通信のキャンセルを要求します。独自 Provider がキャンセルを無視しても、古い応答が新しい会話のメッセージ、ID、使用量、エラーを書き換えることはありません。コンポーネントの setup または Vue effect scope 内で使う場合、scope の破棄時に自動停止します。scope 外では呼び出し側で <code>stop()</code> を実行してください。</p><p>スクロールはメッセージ数、最後のメッセージ本文、生成状態だけを DOM 更新後に監視し、トークンごとの全履歴走査を避けます。コピー失敗時には案内を表示し、1.2 秒後に消去します。新しい会話の開始やコンポーネントの破棄後に、古いコピー結果は表示されません。</p><p><a href="./request">API</a> · <a href="./testing">テスト</a></p>`,15)])])}const g=a(o,[["render",d]]);export{k as __pageData,g as default};
